private FloatBuffer getBuffer4f(float v1, float v2, float v3, float v4) {
		this.buffer4f.clear();
		this.buffer4f.put(v1).put(v2).put(v3).put(v4);
		this.buffer4f.flip();
		return this.buffer4f;
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent(priority = EventPriority.LOWEST)
	public static void onRenderLivingPre(RenderLivingEvent.Pre<EntityLivingBase> event) {
		EntityLivingBase living = event.getEntity();

		IPuppetCapability cap = living.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);
		if (cap != null && cap.hasPuppeteer()) {
			if (!RenderUtils.doesRendererHaveLayer(event.getRenderer(), LayerPuppetOverlay.class, false)) {
				event.getRenderer().addLayer(new LayerPuppetOverlay(event.getRenderer()));
			}
		}
	}

public static boolean doesRendererHaveLayer(RenderLivingBase<?> renderer, Class<? extends LayerRenderer<?>> cls, boolean subclasses) {
		return getRenderLayer(renderer, cls, subclasses) != null;
	}

@SuppressWarnings("unchecked")
	public static <T extends LayerRenderer<?>> T getRenderLayer(RenderLivingBase<?> renderer, Class<T> cls, boolean subclasses) {
		try {
			List<? extends LayerRenderer<?>> layers = renderer.layerRenderers;
			for(LayerRenderer<?> layer : layers) {
				if(subclasses ? cls.isInstance(layer) : cls == layer.getClass()) {
					return (T) layer;
				}
			}
		} catch(Exception ex) {
			throw new RuntimeException(ex);
		}
		return null;
	}

@Override
	public void setPuppeteer(Entity puppeteer) {
		this.puppeteerUUID = puppeteer == null ? null : puppeteer.getUniqueID();
		this.puppeteer = puppeteer;
		this.markDirty();
	}

@Override
	public boolean hasPuppeteer() {
		return this.puppeteerUUID != null;
	}

@Override
	public Entity getPuppeteer() {
		if(this.puppeteerUUID == null) {
			this.puppeteer = null;
		} else if(this.puppeteer == null || !this.puppeteer.isEntityAlive() || !this.puppeteer.getUniqueID().equals(this.puppeteerUUID)) {
			this.puppeteer = null;
			for(Entity entity : this.getEntity().getEntityWorld().getEntitiesWithinAABB(Entity.class, this.getEntity().getEntityBoundingBox().grow(24.0D, 24.0D, 24.0D))) {
				if(entity.getUniqueID().equals(this.puppeteerUUID)) {
					this.puppeteer = entity;
					break;
				}
			}
		}
		return this.puppeteer;
	}

@Override
	public void writeTrackingDataToNBT(NBTTagCompound nbt) {
		if(this.puppeteerUUID != null) {
			nbt.setUniqueId("puppeteer", this.puppeteerUUID);
		}
		nbt.setBoolean("stay", this.stay);
		nbt.setBoolean("guard", this.guard);
	}

@Override
	public void readTrackingDataFromNBT(NBTTagCompound nbt) {
		if(nbt.hasUniqueId("puppeteer")) {
			this.puppeteerUUID = nbt.getUniqueId("puppeteer");
		} else {
			this.puppeteerUUID = null;
			this.puppeteer = null;
		}
		this.stay = nbt.getBoolean("stay");
		this.guard = nbt.getBoolean("guard");
	}

