public static boolean isLayerSafe(BlendMode mode) {
        // Blending off means "replace the destination". In a standalone layer the destination is
        // transparent black and the alpha channel is coverage, so a fragment whose shader alpha is
        // below 1 ends up SEMI-TRANSPARENT against the scene instead of opaque — and no fixed-function
        // blend state can pin coverage to 1 independently of the source alpha. Draw these in place
        // rather than quietly change how they look. (Iris has no in-place path, so
        // applyPremultiplied still handles the case for it.)
        if (!mode.isEnableBlend()) return false;
        if (!isDestinationFree(mode.getSrcColorFactor())) return false;
        var dstColor = mode.getDstColorFactor();
        return switch (mode.getBlendFunc()) {
            case ADD -> dstColor == DestFactor.ZERO
                    || dstColor == DestFactor.ONE_MINUS_SRC_ALPHA
                    || dstColor == DestFactor.ONE;
            case REVERSE_SUB -> dstColor == DestFactor.ONE;
            default -> false;
        };
    }

public static boolean areLayerSafe(List<MaterialSetting> materials) {
        for (var material : materials) {
            if (!isLayerSafe(material.getEffectiveBlendMode())) return false;
        }
        return true;
    }

private static void applyCoverageFree(SourceFactor srcColor, int equation) {
        apply(srcColor, DestFactor.ONE, SourceFactor.ZERO, DestFactor.ONE, equation);
    }

private static void apply(SourceFactor srcColor, DestFactor dstColor,
                              SourceFactor srcAlpha, DestFactor dstAlpha, int equation) {
        RenderSystem.enableBlend();
        RenderSystem.blendEquation(equation);
        RenderSystem.blendFuncSeparate(srcColor, dstColor, srcAlpha, dstAlpha);
    }

private static boolean isDestinationFree(SourceFactor factor) {
        return switch (factor) {
            case DST_COLOR, ONE_MINUS_DST_COLOR, DST_ALPHA, ONE_MINUS_DST_ALPHA -> false;
            default -> true;
        };
    }

public void pre() {
        var followed = getFollowedRenderState();
        appliedBlend = followed != null ? followed.blendMode() : blendMode;
        appliedCull = followed != null ? followed.cull() : cull;
        appliedDepthTest = followed != null ? followed.depthTest() : depthTest;
        appliedDepthMask = followed != null ? followed.depthMask() : depthMask;
        var pipeline = RenderPassPipeline.getCurrent();
        if (pipeline != null && pipeline.isPremultipliedAccumulation()) {
            PremultipliedBlendPlan.applyPremultiplied(appliedBlend);
        } else {
            appliedBlend.apply();
        }
        if (appliedCull) RenderSystem.enableCull(); else RenderSystem.disableCull();
        if (appliedDepthTest) RenderSystem.enableDepthTest(); else RenderSystem.disableDepthTest();
        RenderSystem.depthMask(appliedDepthMask);
    }

public void post() {
        if (appliedTwoPass) {
            GL11.glCullFace(GL11.GL_BACK);
            appliedTwoPass = false;
        }
        if (appliedBlend.getBlendFunc() != BlendMode.BlendFuc.ADD) {
            RenderSystem.blendEquation(BlendMode.BlendFuc.ADD.op);
        }
        appliedBlend.reset();
        if (!appliedCull) RenderSystem.enableCull();
        if (!appliedDepthTest) RenderSystem.enableDepthTest();
        if (!appliedDepthMask) RenderSystem.depthMask(true);
    }

public BlendMode getEffectiveBlendMode() {
        var followed = getFollowedRenderState();
        return followed != null ? followed.blendMode() : blendMode;
    }

@Nullable
    public MaterialRenderState getFollowedRenderState() {
        return renderStateSource == RenderStateSource.MATERIAL ? material.getPreferredRenderState() : null;
    }

public boolean isPremultipliedAccumulation() {
        return (irisTarget != null || lateLayer) && !maskSubPass;
    }

private Map<PhotonFXRenderPass, Queue<IParticle>> routePasses() {
        lateGroup = null;
        // Under a shader pack there is nothing to split TO: every pass already accumulates into one
        // layer, and unreproducible blends are approximated rather than rerouted.
        if (irisTarget != null || !isLateCapablePipeline()) return particles;

        boolean anyInline = false;
        boolean anyLate = false;
        for (var entry : particles.entrySet()) {
            // an empty queue draws nothing; letting it vote would allocate and composite a blank
            // layer, and would keep the depth snapshot armed, for a pass with no particles in it
            if (entry.getValue().isEmpty()) continue;
            if (isLatePass(entry.getKey())) anyLate = true; else anyInline = true;
            if (anyInline && anyLate) break;
        }
        if (!anyLate) return particles;
        // Something wants the layer, so keep the snapshot coming even when the global default is
        // VANILLA. Recorded BEFORE the availability check on purpose: that is what arms the capture
        // for an emitter-level override, which would otherwise never get a snapshot to route into.
        OpaqueDepthCapture.demand();
        // No snapshot this frame means no depth to test against — anything drawn into the layer
        // would float in front of the terrain. Fall back rather than render something visibly broken.
        if (!OpaqueDepthCapture.hasCaptureThisFrame()) return particles;
        if (!anyInline) {
            lateGroup = particles;
            return Map.of();
        }
        var inline = new TreeMap<PhotonFXRenderPass, Queue<IParticle>>(makeRenderPassComparator());
        var late = new TreeMap<PhotonFXRenderPass, Queue<IParticle>>(makeRenderPassComparator());
        for (var entry : particles.entrySet()) {
            (isLatePass(entry.getKey()) ? late : inline).put(entry.getKey(), entry.getValue());
        }
        lateGroup = late;
        return inline;
    }

private static boolean isLatePass(PhotonFXRenderPass pass) {
        return pass.renderer.getCompositeMode().resolve() == FXCompositeMode.LATE
                && PremultipliedBlendPlan.areLayerSafe(pass.renderer.getMaterials());
    }

public static void compositePremultipliedToBound(int colorTexture, int alphaTexture, boolean writeAlpha) {
        RenderSystem.assertOnRenderThread();
        var shader = PhotonShaders.getIrisCompositeShader();
        if (shader == null) return;
        shader.setSampler("DiffuseSampler", colorTexture);
        shader.setSampler("AlphaSampler", alphaTexture);
        shader.apply();

        GlStateManager._enableBlend();
        GlStateManager._blendEquation(GL14.GL_FUNC_ADD);
        GlStateManager._blendFuncSeparate(GL11.GL_ONE, GL11.GL_ONE_MINUS_SRC_ALPHA,
                GL11.GL_ONE, GL11.GL_ONE_MINUS_SRC_ALPHA);
        GlStateManager._colorMask(true, true, true, writeAlpha);
        GlStateManager._disableDepthTest();
        GlStateManager._depthMask(false);
        drawFullscreenQuad();
        shader.clear();

        GlStateManager._colorMask(true, true, true, true);
        GlStateManager._depthMask(true);
        GlStateManager._enableDepthTest();
        RenderSystem.defaultBlendFunc();
    }

