private void renderGroup(Map<PhotonFXRenderPass, Queue<IParticle>> group, boolean late, boolean lastGroup) {
        activeGroup = group;
        lateLayer = late;
        beforeRendering();
        RenderSystem.setShader(GameRenderer::getParticleShader);
        RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
        // the draw target was freshly prepared -> stale sampler. The late path has to set the flag
        // directly: markSceneSamplerDirty() deliberately swallows it there (see its javadoc), but
        // the first sample of a build still needs a fresh copy of the frame.
        if (late) {
            IS_SCENE_SAMPLER_DIRTY = true;
        } else {
            markSceneSamplerDirty();
        }

        // shaded sub-pass (DRAW and BOTH)
        if (drawMode != SceneView.DrawMode.WIREFRAME) {
            wireframeSubPass = false;
            renderQueuedPasses();
            // in place, the working copy is bent once every effect is on it; the late/after-pack paths bend at their composite
            if (!late && irisTarget == null) StackedDistortion.bend(DRAW_TARGET, depthOf(DRAW_TARGET));
        }
        // wireframe overlay sub-pass (WIREFRAME and BOTH): global polygon LINE mode + the inverse
        // material draws each mesh as inverted-color lines over the (optional) shaded pass.
        if (drawMode != SceneView.DrawMode.DRAW) {
            wireframeSubPass = true;
            GL30.glPolygonMode(GL30.GL_FRONT_AND_BACK, GL30.GL_LINE);
            GL30.glEnable(GL30.GL_POLYGON_OFFSET_LINE);
            GL30.glPolygonOffset(-1.0f, -1.0f);
            renderQueuedPasses();
            GL30.glPolygonOffset(0f, 0f);
            GL30.glDisable(GL30.GL_POLYGON_OFFSET_LINE);
            GL30.glPolygonMode(GL30.GL_FRONT_AND_BACK, GL30.GL_FILL);
            wireframeSubPass = false;
        }

        if (lastGroup) {
            activeGroup = particles;
            renderMaskSubPass();
            activeGroup = group;
        }

        afterRendering();
    }

private void renderQueuedPasses() {
        for (var entry : activeGroup.entrySet()) {
            var renderPass = entry.getKey();
            var particleQueue = entry.getValue();
            if (!particleQueue.isEmpty()) {
                renderPass.prepareStatus(this);
                var drewSomething = renderPass.drawParticles(this, particleQueue, camera, partialTicks);
                renderPass.releaseStatus(this);
                if (drewSomething) {
                    // only a pass that wrote pixels can change what a later scene-sampling
                    // material sees; skipping the mark avoids a redundant scene re-copy
                    markSceneSamplerDirty();
                }
            }
        }
    }

public static void clearFrameMask() {
        maskColorTexture = -1;
        maskDepthTexture = -1;
        // a frame that produced a deferred layer but never reached the composite hook (screenshot
        // paths, a cancelled level render) must not leak it into the next frame
        pendingLateLayer = null;
        lateLayerStarted = false;
        StackedDistortion.endFrame();
        // likewise the opaque depth snapshot: a frame that never reached AFTER_BLOCK_ENTITIES must
        // not depth-test this frame's FX against last frame's geometry
        OpaqueDepthCapture.endFrame();
    }

@Override
    public @Nullable MeshData build() {
        if (particles.isEmpty()) return null;
        // The shadow pass re-runs world geometry into a different framebuffer, at a different
        // resolution, with a different projection. Nothing we resolve or draw would be valid there,
        // and writing into the pack's shadow map is actively harmful.
        if (IrisCompat.isShadowPass()) {
            clearRenderingState();
            return null;
        }
        // Resolve BEFORE anything binds a framebuffer: resolution goes through Iris' ShaderMap, so
        // it does not depend on MC's main target still being bound (which is what the shader-getter
        // override keys off).
        irisTarget = IrisCompat.resolveFrameTarget(this == ParticleQueueRenderType.TRANSLUCENT_QUEUE.pipeline);
        if (irisTarget != null && !irisTarget.canComposite()) {
            clearRenderingState();
            irisTarget = null;
            return null;
        }
        current = this;
        var mode = PhotonParticleManager.getDrawMode();
        drawMode = mode == null ? SceneView.DrawMode.DRAW : mode;

        var inlineGroup = routePasses();
        if (irisTarget != null || lateGroup != null) {
            // Only the deferring paths hand the framebuffer back; capturing this when the write-back
            // is going to bind MC's main target anyway would cost a synchronous glGet and three
            // allocations per build for nothing.
            entryFramebuffer = GlStateManager.getBoundFramebuffer();
            entryViewport = PositionedRect.of(GlStateManager.Viewport.x(), GlStateManager.Viewport.y(),
                    GlStateManager.Viewport.width(), GlStateManager.Viewport.height());
        }
        // A throwing pass must not latch the pipeline into a half-built state: `lateLayer` stuck true
        // would send the NEXT build down the layer path with a stale depth attachment, a stuck
        // `current` would keep every material reading a dead pipeline, and — worst of the three — our
        // own framebuffer would still be bound, so the whole rest of the level render would land in
        // it. (That is exactly what the missing-water bug looked like.) The frame is lost either way;
        // the point is that the frame after it is not.
        boolean completed = false;
        try {
            if (!inlineGroup.isEmpty()) {
                renderGroup(inlineGroup, false, lateGroup == null);
            }
            if (lateGroup != null) {
                renderGroup(lateGroup, true, true);
            }
            completed = true;
        } finally {
            if (!completed) {
                UISurface.currentTarget().bindWrite(true);
                GL11.glCullFace(GL11.GL_BACK);
                RenderSystem.blendEquation(GL14.GL_FUNC_ADD);
            }
            clearRenderingState();
            current = null;
        }
        return null;
    }

public final boolean drawParticles(RenderPassPipeline pipeline, Collection<IParticle> particles, Camera camera, float partialTicks) {
        var materials = getMaterials(pipeline);
        if (materials.isEmpty()) return false;
        if (pipeline.isMaskSubPass()) {
            CURRENT_MASK_VALUE = com.lowdragmc.photon.client.postfx.runtime.MaskGroups
                    .idOf(renderer.getMaskGroup()) / 255f;
            var cutoff = renderer.getMaskAlphaCutoff();
            CURRENT_MASK_TEXTURE = cutoff > 0 ? findMaskClipTexture() : null;
            // no clippable texture on the pass -> fall back to the flat geometry mask
            CURRENT_MASK_CUTOFF = CURRENT_MASK_TEXTURE != null ? cutoff : 0f;
        }
        return drawParticlesInternal(materials, pipeline, particles, camera, partialTicks);
    }

protected final boolean drawParticlesInternal(List<MaterialSetting> materials, RenderPassPipeline pipeline, Collection<IParticle> particles, Camera camera, float partialTicks) {
        if (useInstancing()) {
            return drawInstanced(materials, pipeline, particles, camera, partialTicks);
        }

        var records = beginCpuRecords(materials, particles.size());

        // prepare mesh data
        var buffer = begin(Tesselator.getInstance());
        try {
            renderQueue(buffer, particles, camera, partialTicks);
        } finally {
            if (records) endCpuRecords();
        }
        var meshData = buffer.build();
        if (meshData == null) return false;

        // sort quads if necessary
        var sorting = getSorting();
        if (sorting != null) {
            var result = MeshDataSorter.sortPrimitives(meshData, pipeline.getSortingBuffer(), sorting);
            if (result != null) {
                result.applyTo(meshData);
            }
        }

        // upload to vbo
        var vbo = uploadFormatVbo(meshData);

        // render materials
        for (var materialSetting : materials) {
            for (int pass = 0, passes = materialSetting.passes(); pass < passes; pass++) {
                materialSetting.pre(pass);
                var material = materialSetting.getMaterial();
                if (records && readsParticleRecords(material)) {
                    renderWithCpuRecords(material, vbo);
                } else {
                    renderWithMaterial(material, MaterialContext.NORMAL, vbo);
                }
                materialSetting.post();
            }
        }

        // invalidate cache
        BufferUploader.invalidate();
        return true;
    }

protected List<MaterialSetting> getMaterials(RenderPassPipeline pipeline) {
        if (pipeline.isMaskSubPass()) {
            // only flagged passes participate in the mask sub-pass (empty = skipped entirely)
            return renderer.isWriteCustomMask() ? List.of(MASK_MATERIAL) : List.of();
        }
        var materials = renderer.getMaterials();
        if (pipeline.isWireframeSubPass()) {
            materials = List.of(WIREFRAME_MATERIAL);
        }
        return materials;
    }

@Nullable
    private net.minecraft.resources.ResourceLocation findMaskClipTexture() {
        for (var materialSetting : renderer.getMaterials()) {
            if (getRawMaterial(materialSetting.getMaterial()) instanceof TextureMaterial textureMaterial) {
                return textureMaterial.getTexture();
            }
        }
        return null;
    }

private static IMaterial getRawMaterial(IMaterial material) {
        if (material instanceof UIResourceMaterial uiResourceMaterial) {
            return uiResourceMaterial.getRawMaterial();
        }
        return material;
    }

public static synchronized int idOf(String group) {
        var name = group == null || group.isBlank() ? DEFAULT_GROUP : group;
        var existing = IDS.get(name);
        if (existing != null) return existing;
        if (IDS.size() >= MAX_GROUPS) {
            if (!overflowLogged) {
                overflowLogged = true;
                Photon.LOGGER.warn("more than {} distinct CustomMask groups this session — '{}' aliases id {}",
                        MAX_GROUPS, name, MAX_GROUPS);
            }
            return MAX_GROUPS;
        }
        int id = IDS.size() + 1;
        IDS.put(name, id);
        return id;
    }

public static synchronized void clearAll() {
        IDS.clear();
        overflowLogged = false;
    }

public boolean hasPendingMaskConsumer() {
        if (!effectsEnabled || !com.lowdragmc.photon.PhotonConfig.INSTANCE.enableCustomEffects.get()) return false;
        for (var request : requests) {
            if (request.params().containsKey(CompiledEffect.MASK_FILTER_PARAM)) return true;
            var effect = resolveEffect(request.effect());
            if (effect != null && effect.usesCustomMask()) return true;
        }
        return false;
    }

