@Override
	public void doRenderLayer(T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.depthMask(!entity.isInvisible());

		float scrollTimer = entity.ticksExisted + partialTicks;
		this.renderer.bindTexture(this.overlay);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float yScroll = scrollTimer * 0.002F;
		GlStateManager.translate(0F, -yScroll, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		float colour = 0.5F;
		GlStateManager.color(colour, colour, colour, 1.0F);

		GlStateManager.enablePolygonOffset();
		GlStateManager.doPolygonOffset(0.0F, -5.0F);

		ModelBase mainModel = this.renderer.getMainModel();
		mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
		mainModel.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

		GlStateManager.disablePolygonOffset();

		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.popMatrix();
	}

@Override
	public void doRenderLayer(EntityTarBeast entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.depthMask(!entity.isInvisible());

		float scrollTimer = entity.ticksExisted + partialTicks;
		this.renderer.bindTexture(OVERLAY_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float yScroll = scrollTimer * 0.002F;
		GlStateManager.translate(0F, -yScroll, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		float colour = 0.5F;
		GlStateManager.color(colour, colour, colour, 1.0F);

		ModelTarBeast mainModel = (ModelTarBeast) this.renderer.getMainModel();
		mainModel.drippingtar1_keepstraight.showModel = false;
		mainModel.drippingtar2_keepstraight.showModel = false;
		mainModel.teeth_keepstraight.showModel = false;
		mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
		mainModel.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);
		mainModel.drippingtar1_keepstraight.showModel = true;
		mainModel.drippingtar2_keepstraight.showModel = true;
		mainModel.teeth_keepstraight.showModel = true;

		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		this.renderer.bindTexture(this.renderer.getEntityTexture(entity));

		if(entity.isShedding()) {
			float sheddingScale = (float)(entity.getSheddingProgress() * entity.getSheddingProgress() * 0.002F) + 1.0F;

			GlStateManager.color(1, 1, 1, 0.6F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();

			sheddingScale = (float)(entity.getSheddingProgress() * entity.getSheddingProgress() * 0.004F) + 1.0F;

			GlStateManager.color(1, 1, 1, 0.3F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();
		}

		if(entity.isPreparing()) {
			float sheddingScale = (float)((1.0F - (entity.ticksExisted % 8) / 8.0F) * 0.15F + 1.0F);

			GlStateManager.color(1, 1, 1, 0.6F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();

			sheddingScale = (float)((1.0F - (entity.ticksExisted % 8) / 8.0F) * 0.2F + 1.05F);

			GlStateManager.color(1, 1, 1, 0.3F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();
		}

		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
	}

public static void renderTransparentCuboid(PoseStack matrices, MultiBufferSource buffer, FluidCuboid cube, FluidStack fluid, int opacity, int light) {
    // nothing to render? skip
    if (opacity < 0 || fluid.isEmpty()) {
      return;
    }

    IClientFluidTypeExtensions attributes = IClientFluidTypeExtensions.of(fluid.getFluid());
    TextureAtlasSprite still = FluidRenderer.getBlockSprite(attributes.getStillTexture(fluid));
    TextureAtlasSprite flowing = FluidRenderer.getBlockSprite(attributes.getFlowingTexture(fluid));
    FluidType fluidType = fluid.getFluid().getFluidType();
    boolean isGas = fluidType.isLighterThanAir();
    light = FluidRenderer.withBlockLight(light, fluidType.getLightLevel(fluid));

    // add in fluid opacity if given
    int color = attributes.getTintColor(fluid);
    if (opacity < 0xFF) {
      // alpha is top 8 bits, multiply by opacity and divide out remainder
      int alpha = ((color >> 24) & 0xFF) * opacity / 0xFF;
      // clear bits in color and or in the new alpha
      color = (color & 0xFFFFFF) | (alpha << 24);
    }
    FluidRenderer.renderCuboid(matrices, buffer.getBuffer(MantleRenderTypes.FLUID), cube, still, flowing, cube.getFromScaled(), cube.getToScaled(), color, light, isGas);
  }

@Override
        public void render(PoseStack pMatrixStack, AbstractSpellCastingMob pLivingEntity, BakedGeoModel bakedModel, RenderType renderType2, MultiBufferSource bufferSource, VertexConsumer buffer, float pPartialTicks, int packedLight, int packedOverlay) {
            float percent = getRenderPercent(pLivingEntity);
            if (percent > 0) {
                float f = (float) pLivingEntity.tickCount + pPartialTicks;
                float offset = Mth.sin(f * 2) * 0.75f * percent;
                pMatrixStack.translate(offset, 0, 0);
                pMatrixStack.scale(1.01f, 1.01f, 1.01f);
                int color = RenderHelper.colorf(.988f * percent, .313f * percent, .968f * percent, percent);
                var type = RenderHelper.CustomerRenderType.magic(this.getRenderer().getTextureLocation(pLivingEntity));
                this.getRenderer().actuallyRender(pMatrixStack, pLivingEntity, bakedModel, type, bufferSource, bufferSource.getBuffer(type), true, pPartialTicks, LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color);
            }
        }
